// k1's first 12 edges passed. The second entry repeated the 20-left path and
// opened Grid Settings, because the menu cursor stays on the AF section.
// The second entry presses Menu once, enters the remembered item if the AF
// page is not already showing, then moves to the AF Target row.
// Do not edit this file after it has run.
// Usage: node26 work/scripts/accept_edges_k2.mjs om-emu
import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { pathToFileURL } from 'node:url';
import { runZone } from './zone_session_k1.mjs';

const [checkout] = process.argv.slice(2);
if (!checkout) {
  process.stderr.write('usage: node26 work/scripts/accept_edges_k2.mjs om-emu\n');
  process.exit(2);
}
const OUT = resolve('work/out/accept-edges-k2.jsonl');
const lines = [];
let stopped = false;
const emit = (row) => {
  lines.push(JSON.stringify(row));
  console.log(JSON.stringify(row));
  mkdirSync(resolve('work/out'), { recursive: true });
  writeFileSync(OUT, lines.join('\n') + '\n');
};
const same = (a, b) => JSON.stringify(a) === JSON.stringify(b);
const EDGES = [
  ['s1', 'down'], ['s1', 'up'],
  ['afon', 'down'], ['afon', 'up'],
  ['s1', 'down'], ['afon', 'down'], ['afon', 'up'], ['s1', 'up'],
  ['afon', 'down'], ['s1', 'down'], ['s1', 'up'], ['afon', 'up'],
];
const OWNERS = [1, 0, 2, 0, 1, 2, 1, 0, 2, 2, 2, 0];
const HALF_EDGES = new Set([0, 1, 3, 4, 6, 7, 11]);
const SINGLE = [0x0e, 0x02, 0x00, 0x00, 0x01, 0x00, 0x01, 0x00, 0x00, 0x00];
const SMALL = [0x0e, 0x02, 0x03, 0x00, 0x01, 0x00, 0x01, 0x00, 0x00, 0x00];
const ALL = [0x0e, 0x02, 0x02, 0x00, 0x01, 0x00, 0x01, 0x00, 0x00, 0x00];
const HALF = [0x0e, 0x02, 0x03, 0x00, 0x03, 0x00, 0x03, 0x00, 0x00, 0x00];
const STOCK_TARGET = [0x0e, 0x02, 0x02, 0x00, 0x1b, 0x00, 0x27, 0x00, 0x00, 0x00];
const CELLS = {
  k90a1: [1, 1],
  k1dd1: [3, 3, 3, 3, 3, 3, 3, 3, 3, 3],
  k99a1: [2, 0, 2, 0, 2, 0, 5, 5],
  k9a41: 0,
  k5962: [526, 526, 526, 526, 526, 526],
  home: {
    '0x99d2': [526, 526, 526], '0x9fa1': [0, 0, 0], '0xdfa1': [0], '0x1ea1': [0],
    '0x9ec1': [0], '0x9ed1': [1], '0x9ee1': [0], '0x9ef1': [0], '0x59b1': [0],
  },
};
let API_SET = 0;
async function bindApi() {
  const { A } = await import(pathToFileURL(resolve(checkout, 'emu/src/fw/model.mjs')).href);
  API_SET = A(0x50ac4afe);
}
function watched(cells) {
  return {
    k90a1: cells.k90a1, k1dd1: cells.k1dd1, k99a1: cells.k99a1,
    k9a41: cells.k9a41, k5962: cells.k5962, home: cells.home,
  };
}
async function prepare(ctx) {
  await bindApi();
  ctx.bringUp();
  ctx.s.switch_input('lever', 1);
  ctx.s.camapp.pump();
  ctx.idle(500);
  const argument = ctx.l.call(ctx.native(0x604050e5), { d0: 289, d1: 0 }, null, null, 200000).d0 >>> 0;
  ctx.l.call(API_SET, { d0: 289, d1: argument }, null, null, 200000);
  ctx.l.call(API_SET, { d0: 1712, d1: 0 }, null, null, 200000);
  ctx.idle(500);
}
async function choose(ctx, rights, value) {
  ctx.press('menu');
  for (let i = 0; i < 20; i++) ctx.press('left');
  ctx.press('down');
  ctx.press('down');
  ctx.press('ok');
  ctx.press('down');
  ctx.press('down');
  ctx.press('ok');
  for (let i = 0; i < rights; i++) ctx.press('right');
  const shot = ctx.shot('zone-' + value);
  ctx.press('ok');
  for (let i = 0; i < 8 && ctx.s.screen() !== 'shooting'; i++) ctx.press('menu');
  const profile = ctx.readByte(ctx.PROFILE);
  emit({ session: ctx.tag, record: 'zone', value, rights, profile, screen: ctx.s.screen(), texts: shot.texts });
  if (ctx.s.screen() !== 'shooting') throw new Error('not shooting after zone ' + value);
  if (profile !== value) throw new Error('profile ' + profile + ' wanted ' + value);
}
async function chooseRemembered(ctx, rights, value) {
  ctx.press('menu');
  let view = ctx.screen();
  emit({ session: ctx.tag, record: 'remembered-open', texts: view.texts, highlight: view.highlight });
  const onAf = (v) => (v.texts || []).some((t) => t.includes('AF Button') || t.includes('AF Target'));
  if (!onAf(view)) {
    ctx.press('ok');
    view = ctx.screen();
    emit({ session: ctx.tag, record: 'remembered-enter', texts: view.texts, highlight: view.highlight });
  }
  for (let i = 0; i < 4 && view.highlight !== '@A040@AF Target Mode'; i++) {
    ctx.press('down');
    view = ctx.screen();
  }
  if (view.highlight !== '@A040@AF Target Mode') {
    throw new Error('zone row not found: ' + JSON.stringify(view.texts));
  }
  ctx.press('ok');
  for (let i = 0; i < rights; i++) ctx.press('right');
  const shot = ctx.shot('zone-' + value);
  ctx.press('ok');
  for (let i = 0; i < 8 && ctx.s.screen() !== 'shooting'; i++) ctx.press('menu');
  const profile = ctx.readByte(ctx.PROFILE);
  emit({ session: ctx.tag, record: 'zone', value, rights, profile, screen: ctx.s.screen(), texts: shot.texts, via: 'remembered' });
  if (ctx.s.screen() !== 'shooting') throw new Error('not shooting after zone ' + value);
  if (profile !== value) throw new Error('profile ' + profile + ' wanted ' + value);
}
function checkEdge(ctx, name, index, profile, afon) {
  const cells = ctx.cells();
  const own = ctx.readOwn();
  const got = {
    target: ctx.readTarget(),
    owner: ctx.candidate ? own[4] : null,
    status: ctx.candidate ? own[5] : null,
    enabled: ctx.candidate ? own[6] : null,
    profile: cells.profile,
    focus: ctx.s.get(289),
    subject: ctx.s.get(1712),
    cells: watched(cells),
  };
  const target = !ctx.candidate ? STOCK_TARGET : (HALF_EDGES.has(index) ? HALF : afon);
  const problems = [];
  if (!same(got.target, target)) problems.push('target');
  if (got.focus !== 0) problems.push('focus');
  if (got.subject !== 0) problems.push('subject');
  if (!same(got.cells, CELLS)) problems.push('cells');
  if (ctx.candidate) {
    if (got.profile !== profile) problems.push('profile');
    if (got.owner !== OWNERS[index]) problems.push('owner');
    if (got.status !== 0) problems.push('status');
    if (got.enabled !== 1) problems.push('enabled');
  }
  emit({
    session: name, edge: index, key: EDGES[index][0], dir: EDGES[index][1],
    pass: problems.length === 0, problems, got, expect: { target, profile: ctx.candidate ? profile : null, owner: ctx.candidate ? OWNERS[index] : null },
  });
  if (problems.length) throw new Error(name + ' edge ' + index + ' ' + problems.join(','));
}
async function edges(ctx, name, profile, afon) {
  for (let i = 0; i < EDGES.length; i++) {
    ctx.key(EDGES[i][0], EDGES[i][1]);
    ctx.idle(600);
    checkEdge(ctx, name, i, profile, afon);
  }
}
function stores(file) {
  const doc = JSON.parse(readFileSync(resolve(file), 'utf8'));
  return { M: Buffer.from(doc.M, 'base64'), E: Buffer.from(doc.E, 'base64') };
}

async function lane(name, candidate, nvram, drive) {
  const result = await runZone({
    checkout,
    outPath: 'work/out/session-accept2-' + name + '.jsonl',
    tag: 'accept2-edge-' + name,
    candidate,
    help: true,
    rowLabel: true,
    overlayCsv: candidate ? 'work/out/overlay-changed-bytes.csv' : null,
    nvramPath: nvram,
    fatalShots: true,
    explanation: candidate
      ? name + ' acceptance on the swapped overlay. Role: behaviour.'
      : name + ' stock control, same edges, no AF-ON overlay.',
    change: candidate ? 'profile source swap' : 'none',
    drive,
  });
  if (!result.ok) throw new Error(name + ' failed: ' + result.failed);
}

try {
  await lane('control', false, 'work/out/nvram-accept2-control.json', async (ctx) => {
    await prepare(ctx);
    await edges(ctx, 'control', null, null);
  });
  for (const name of ['c1', 'c2']) {
    if (stopped) break;
    await lane(name, true, 'work/out/nvram-accept2-' + name + '.json', async (ctx) => {
      await prepare(ctx);
      await choose(ctx, 1, 1);
      await edges(ctx, name + '-single', 1, SINGLE);
      await chooseRemembered(ctx, 1, 2);
      await edges(ctx, name + '-small', 2, SMALL);
    });
  }
  const control = stores('work/out/nvram-accept2-control.json');
  for (const name of ['c1', 'c2']) {
    const store = stores('work/out/nvram-accept2-' + name + '.json');
    const sameM = control.M.equals(store.M);
    const sameE = control.E.equals(store.E);
    emit({ record: 'store', session: name, pass: sameM && sameE, sameM, sameE, mBytes: store.M.length, eBytes: store.E.length });
    if (!sameM || !sameE) throw new Error('store mismatch ' + name);
  }
  await lane('reopen', true, 'work/out/nvram-accept2-c1.json', async (ctx) => {
    await prepare(ctx);
    const profile = ctx.readByte(ctx.PROFILE);
    emit({ session: 'reopen', record: 'profile', profile });
    if (profile !== 0) throw new Error('reopen profile ' + profile);
    ctx.key('afon', 'down');
    ctx.idle(600);
    const got = { target: ctx.readTarget(), owner: ctx.readOwn()[4], profile: ctx.readByte(ctx.PROFILE) };
    const pass = same(got.target, ALL) && got.owner === 2 && got.profile === 0;
    emit({ session: 'reopen', record: 'default-zone', pass, got, expect: { target: ALL, owner: 2, profile: 0 } });
    if (!pass) throw new Error('default zone');
    ctx.key('afon', 'up');
    ctx.idle(300);
  });
  emit({ record: 'done', ok: true });
} catch (e) {
  emit({ record: 'done', ok: false, error: String(e && e.stack ? e.stack : e) });
  process.exitCode = 1;
}
